public abstract class AbstractIntegracion implements Comparable<AbstractIntegracion> {
    protected String identificador;
    protected String nombreProveedor;
    protected String estadoConexion;
    protected double latenciaPromedioMs;

   
    public AbstractIntegracion(String identificador, String nombreProveedor, String estadoConexion, double latenciaPromedioMs) {
        this.identificador = identificador;
        this.nombreProveedor = nombreProveedor;
        this.estadoConexion = estadoConexion;
        this.latenciaPromedioMs = latenciaPromedioMs;
    }

   
    public String getIdentificador() { 
        return identificador; 
    }
    public String getNombreProveedor() { 
        return nombreProveedor; 

    }
    public String getEstadoConexion() { 
        return estadoConexion; 
    }
    public double getLatenciaPromedioMs() { 
        return latenciaPromedioMs; 
    }

    // Método de la interfaz Comparable: ordena por latencia de menor a mayor, y desempata alfabéticamente por ID
    @Override
    public int compareTo(AbstractIntegracion otra) {
        int resultadoLatencia = Double.compare(this.latenciaPromedioMs, otra.latenciaPromedioMs);
        if (resultadoLatencia != 0) {
            return resultadoLatencia;
        }
        return this.identificador.compareTo(otra.identificador);
    }

    // Método abstracto que obliga a las subclases concretas a definir su propia representación visual
    public abstract String mostrarDetalles();
}
